import { ConfigurationError } from "@zudojs/errors";

function checkProduction(config) {
  if (config.production && config.jwt_secret === undefined) {
    throw new ConfigurationError("TASKS_JWT_SECRET must be set in production");
  }
  return "ok";
}

for (const config of [
  { production: false },
  { production: true },
  { production: true, jwt_secret: "n8VqT2xLm4pR7sKd9wYb3cFh6jZa1eUo" },
]) {
  try {
    console.log(checkProduction(config));
  } catch (error) {
    console.log(`${error.name}: ${error.message}`);
